CREATE OR REPLACE PROCEDURE test_fetch() LANGUAGE plpgsql AS $$
DECLARE
  rec_id integer := 999;
  cur CURSOR FOR SELECT i FROM generate_series(1,3) AS g(i);
BEGIN
